+    assert.equal(st.pr, 'done');
+    assert.equal(st.review, 'current');
+    assert.equal(st.approve, 'pending');
+    assert.equal(st.merge, 'pending');
+  });
+
+  test('an in-flight head validation shows valid as current, not failed', function () {
