+    { id: 'dev',     name: 'dev',     ts: 'devStartedAt' },
+    { id: 'pr',      name: 'pr',      ts: 'prCreated' },
+    { id: 'valid',   name: 'valid',   ts: 'validatingAt' },
+    { id: 'review',  name: 'review',  ts: 'reviewedAt' },
+    { id: 'approve', name: 'approve', ts: 'approvedAt' },
+    { id: 'merge',   name: 'merge',   ts: 'mergedAt' }
+  ];
+
